def stream_log_lines(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            # yield emite una línea y pausa la ejecución sin acumular memoria
            yield line.strip()

def parse_eventos(lineas):
    for linea in lineas:
        if 'ERROR' in linea:
            yield {'raw': linea}

# Pipeline encadenado: procesa 100 GB consumiendo < 20 MB de memoria
lineas = stream_log_lines('servidor_gigante.log')
errores = parse_eventos(lineas)
for err in errores:
    enviar_a_alerta(err)
